class Solution {
  public boolean maxSubstringLength(String s, int k) {
    int n = s.length();
    int[] first = new int[26], last = new int[26];
    java.util.Arrays.fill(first, -1);
    for (int i = 0; i < n; i++) {
      int c = s.charAt(i) - 'a';
      if (first[c] < 0) first[c] = i;
      last[c] = i;
    }
    int[] endAt = new int[n];
    java.util.Arrays.fill(endAt, -1);
    List<int[]> intervals = new ArrayList<>();
    for (int c = 0; c < 26; c++) {
      if (first[c] < 0) continue;
      int l = first[c], r = last[c];
      boolean valid = true;
      for (int i = l; i <= r && valid; i++) {
        int ch = s.charAt(i) - 'a';
        if (first[ch] < l) valid = false;
        r = Math.max(r, last[ch]);
      }
      if (valid && r - l + 1 < n) intervals.add(new int[] {l, r});
    }
    intervals.sort((x, y) -> Integer.compare(x[1], y[1]));
    int count = 0, end = -1;
    for (int[] iv : intervals) {
      if (iv[0] > end) {
        count++;
        end = iv[1];
      }
    }
    return count >= k;
  }
}
